/*
 * SPECTRA Remote data-only PeerJS transport.
 *
 * This ESM source is derived from PeerJS 1.5.5 (MIT). The complete license and
 * attribution are kept in LICENSE.peerjs. SPECTRA owns this narrow fork so the
 * extension and the public Remote page execute the same source and cannot
 * silently drift between serializers or globals.
 *
 * The PeerJS signaling/WebRTC wire ABI is intentionally retained. Media
 * connections, binary/raw serializers, browser adapter shims, and the global
 * window.Peer export are intentionally absent. Remote application messages are
 * UTF-8 JSON and are bounded before parsing or sending.
 */

const VERSION = '1.5.5';
const CLOUD_HOST = '0.peerjs.com';
const CLOUD_PORT = 443;
const PEER_MESSAGE_LIMIT_BYTES = 16 * 1024;
const MAX_SIGNALING_QUEUE = 64;
const MAX_LOST_MESSAGES = 32;
const MAX_LOST_MESSAGE_CONNECTIONS = 32;
const MAX_BUFFERED_AMOUNT = 8 * 1024 * 1024;
const DEFAULT_CONFIG = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    {
      urls: [
        'turn:eu-0.turn.peerjs.com:3478',
        'turn:us-0.turn.peerjs.com:3478',
      ],
      username: 'peerjs',
      credential: 'peerjsp',
    },
  ],
  sdpSemantics: 'unified-plan',
};

const ConnectionType = Object.freeze({ Data: 'data' });
const PeerErrorType = Object.freeze({
  BrowserIncompatible: 'browser-incompatible',
  Disconnected: 'disconnected',
  InvalidID: 'invalid-id',
  InvalidKey: 'invalid-key',
  Network: 'network',
  PeerUnavailable: 'peer-unavailable',
  ServerError: 'server-error',
  SocketError: 'socket-error',
  SocketClosed: 'socket-closed',
  UnavailableID: 'unavailable-id',
  WebRTC: 'webrtc',
});
const SocketEventType = Object.freeze({
  Message: 'message',
  Disconnected: 'disconnected',
  Error: 'error',
  Close: 'close',
});
const ServerMessageType = Object.freeze({
  Heartbeat: 'HEARTBEAT',
  Candidate: 'CANDIDATE',
  Offer: 'OFFER',
  Answer: 'ANSWER',
  Open: 'OPEN',
  Error: 'ERROR',
  IdTaken: 'ID-TAKEN',
  InvalidKey: 'INVALID-KEY',
  Leave: 'LEAVE',
  Expire: 'EXPIRE',
});

function isRecord(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function randomToken() {
  return Math.random().toString(36).slice(2);
}

function validId(id) {
  return !id || /^[A-Za-z0-9]+(?:[ _-][A-Za-z0-9]+)*$/.test(id);
}

class EventEmitter {
  constructor() {
    this.listeners = new Map();
  }

  on(type, listener) {
    const listeners = this.listeners.get(type) || [];
    listeners.push(listener);
    this.listeners.set(type, listeners);
    return this;
  }

  once(type, listener) {
    const wrapper = (...args) => {
      this.off(type, wrapper);
      listener(...args);
    };
    return this.on(type, wrapper);
  }

  off(type, listener) {
    const listeners = this.listeners.get(type);
    if (!listeners) return this;
    const index = listeners.indexOf(listener);
    if (index >= 0) listeners.splice(index, 1);
    if (listeners.length === 0) this.listeners.delete(type);
    return this;
  }

  removeListener(type, listener) {
    return this.off(type, listener);
  }

  removeAllListeners(type) {
    if (type === undefined) this.listeners.clear();
    else this.listeners.delete(type);
    return this;
  }

  emit(type, ...args) {
    const listeners = this.listeners.get(type);
    if (!listeners) return false;
    for (const listener of [...listeners]) listener(...args);
    return true;
  }
}

class PeerError extends Error {
  constructor(type, value) {
    super(value instanceof Error ? value.message : String(value));
    this.name = 'PeerError';
    this.type = type;
    if (value instanceof Error && value.stack) this.stack = value.stack;
  }
}

class Logger {
  constructor() {
    this.level = 0;
  }

  log(...args) {
    if (this.level >= 3) console.log('PeerJS:', ...args);
  }

  warn(...args) {
    if (this.level >= 2) console.warn('PeerJS:', ...args);
  }

  error(...args) {
    if (this.level >= 1) console.error('PeerJS:', ...args);
  }
}

const logger = new Logger();

const util = Object.freeze({
  CLOUD_HOST,
  CLOUD_PORT,
  chunkedMTU: PEER_MESSAGE_LIMIT_BYTES,
  defaultConfig: DEFAULT_CONFIG,
  supports: Object.freeze({
    browser: true,
    webRTC: typeof RTCPeerConnection !== 'undefined',
    audioVideo: false,
    data: typeof RTCPeerConnection !== 'undefined',
    binaryBlob: false,
    reliable: true,
  }),
  validateId: validId,
  randomToken,
});

class Socket extends EventEmitter {
  constructor(secure, host, port, path, key, pingInterval = 5000) {
    super();
    this.disconnected = true;
    this.id = undefined;
    this.messages = [];
    this.socket = undefined;
    this.pingTimer = undefined;
    this.pingInterval = pingInterval;
    this.baseUrl = `${secure ? 'wss' : 'ws'}://${host}:${port}${path}peerjs?key=${key}`;
  }

  start(id, token) {
    this.id = id;
    if (this.socket || !this.disconnected) return;
    const socket = new WebSocket(`${this.baseUrl}&id=${id}&token=${token}&version=${VERSION}`);
    this.socket = socket;
    this.disconnected = false;
    socket.onmessage = (event) => {
      try {
        this.emit(SocketEventType.Message, JSON.parse(event.data));
      } catch {
        logger.warn('Invalid signaling message');
      }
    };
    socket.onerror = () => this.emit(SocketEventType.Error, 'WebSocket error');
    socket.onclose = (event) => {
      if (this.disconnected) return;
      logger.log('Socket closed.', event);
      this.cleanup();
      this.disconnected = true;
      this.emit(SocketEventType.Disconnected);
    };
    socket.onopen = () => {
      if (this.disconnected) return;
      this.flush();
      this.scheduleHeartbeat();
    };
  }

  scheduleHeartbeat() {
    clearTimeout(this.pingTimer);
    this.pingTimer = setTimeout(() => this.sendHeartbeat(), this.pingInterval);
  }

  sendHeartbeat() {
    if (!this.isOpen()) return;
    this.socket.send(JSON.stringify({ type: ServerMessageType.Heartbeat }));
    this.scheduleHeartbeat();
  }

  isOpen() {
    return this.socket?.readyState === WebSocket.OPEN;
  }

  flush() {
    const queued = this.messages;
    this.messages = [];
    for (const message of queued) this.send(message);
  }

  send(data) {
    if (this.disconnected) return;
    if (!this.id) {
      if (this.messages.length < MAX_SIGNALING_QUEUE) this.messages.push(data);
      else this.emit(SocketEventType.Error, 'Signaling queue is full');
      return;
    }
    if (!this.isOpen()) return;
    if (!isRecord(data) || typeof data.type !== 'string') {
      this.emit(SocketEventType.Error, 'Invalid signaling message');
      return;
    }
    try {
      this.socket.send(JSON.stringify(data));
    } catch (error) {
      this.emit(SocketEventType.Error, error);
    }
  }

  close() {
    if (this.disconnected) return;
    this.disconnected = true;
    this.cleanup();
  }

  cleanup() {
    clearTimeout(this.pingTimer);
    this.pingTimer = undefined;
    if (this.socket) {
      const socket = this.socket;
      socket.onopen = null;
      socket.onmessage = null;
      socket.onerror = null;
      socket.onclose = null;
      this.socket = undefined;
      try {
        socket.close();
      } catch {
        // The socket is already terminal; no recoverable action exists here.
      }
    }
  }
}

class API {
  constructor(options) {
    this.options = options;
  }

  async request(method) {
    const protocol = this.options.secure ? 'https' : 'http';
    const { host, port, path, key } = this.options;
    const url = new URL(`${protocol}://${host}:${port}${path}${key}/${method}`);
    url.searchParams.set('ts', `${Date.now()}${Math.random()}`);
    url.searchParams.set('version', VERSION);
    return fetch(url.href, { referrerPolicy: this.options.referrerPolicy });
  }

  async retrieveId() {
    const response = await this.request('id');
    if (response.status !== 200) throw new Error(`Error. Status:${response.status}`);
    const id = (await response.text()).trim();
    if (!validId(id)) throw new Error('PeerServer returned an invalid ID');
    return id;
  }

  async listAllPeers() {
    const response = await this.request('peers');
    if (response.status !== 200) throw new Error(`Error. Status:${response.status}`);
    return response.json();
  }
}

function messageBytes(data) {
  if (typeof data === 'string') {
    if (data.length > PEER_MESSAGE_LIMIT_BYTES) return null;
    return new TextEncoder().encode(data);
  }
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  return null;
}

class Negotiator {
  constructor(connection) {
    this.connection = connection;
    this.cleaned = false;
  }

  startConnection(options) {
    if (this.cleaned) return;
    const provider = this.connection.provider;
    if (!provider) return;
    let peerConnection;
    try {
      peerConnection = new RTCPeerConnection(provider.options.config);
    } catch (error) {
      provider.emitError(PeerErrorType.WebRTC, error);
      this.connection.close();
      return;
    }
    this.connection.peerConnection = peerConnection;
    this.setupListeners(peerConnection);
    if (options.originator) {
      try {
        const dataChannel = peerConnection.createDataChannel(
          this.connection.label,
          { ordered: !!options.reliable },
        );
        this.connection.initializeDataChannel(dataChannel);
      } catch (error) {
        provider.emitError(PeerErrorType.WebRTC, error);
        this.connection.close();
        return;
      }
      void this.makeOffer(peerConnection);
    } else {
      void this.handleSDP('OFFER', options.sdp, peerConnection);
    }
  }

  setupListeners(peerConnection) {
    const { connection } = this;
    const provider = connection.provider;
    const peerId = connection.peer;
    const connectionId = connection.connectionId;
    peerConnection.onicecandidate = (event) => {
      if (!event.candidate?.candidate || !connection.provider) return;
      connection.provider.socket.send({
        type: ServerMessageType.Candidate,
        payload: {
          candidate: event.candidate,
          type: ConnectionType.Data,
          connectionId,
        },
        dst: peerId,
      });
    };
    peerConnection.oniceconnectionstatechange = () => {
      const state = peerConnection.iceConnectionState;
      if (state === 'failed') {
        provider?.emitError(PeerErrorType.WebRTC, `Negotiation of connection to ${peerId} failed.`);
        connection.close();
      } else if (state === 'closed') {
        provider?.emitError(PeerErrorType.WebRTC, `Connection to ${peerId} closed.`);
        connection.close();
      }
      connection.emit('iceStateChanged', state);
    };
    peerConnection.ondatachannel = (event) => {
      if (!connection.provider || connection.provider !== provider) return;
      const current = provider.getConnection(peerId, connectionId);
      current?.initializeDataChannel(event.channel);
    };
  }

  async makeOffer(peerConnection) {
    const provider = this.connection.provider;
    if (!provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
    try {
      const offer = await peerConnection.createOffer(this.connection.options.constraints);
      if (!this.connection.provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
      await peerConnection.setLocalDescription(offer);
      if (!this.connection.provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
      provider.socket.send({
        type: ServerMessageType.Offer,
        payload: {
          sdp: offer,
          type: ConnectionType.Data,
          connectionId: this.connection.connectionId,
          metadata: this.connection.metadata,
          label: this.connection.label,
          reliable: this.connection.reliable,
          serialization: 'json',
        },
        dst: this.connection.peer,
      });
    } catch (error) {
      if (!this.cleaned && this.connection.provider) {
        provider.emitError(PeerErrorType.WebRTC, error);
        this.connection.close();
      }
    }
  }

  async makeAnswer(peerConnection) {
    const provider = this.connection.provider;
    if (!provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
    try {
      const answer = await peerConnection.createAnswer();
      if (!this.connection.provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
      await peerConnection.setLocalDescription(answer);
      if (!this.connection.provider || this.cleaned || this.connection.peerConnection !== peerConnection) return;
      provider.socket.send({
        type: ServerMessageType.Answer,
        payload: {
          sdp: answer,
          type: ConnectionType.Data,
          connectionId: this.connection.connectionId,
        },
        dst: this.connection.peer,
      });
    } catch (error) {
      if (!this.cleaned && this.connection.provider) {
        provider.emitError(PeerErrorType.WebRTC, error);
        this.connection.close();
      }
    }
  }

  async handleSDP(type, sdp, peerConnection = this.connection.peerConnection) {
    const provider = this.connection.provider;
    if (!provider || this.cleaned || !peerConnection) return;
    try {
      const description = typeof RTCSessionDescription === 'function'
        ? new RTCSessionDescription(sdp)
        : sdp;
      await peerConnection.setRemoteDescription(description);
      if (type === ServerMessageType.Offer) await this.makeAnswer(peerConnection);
    } catch (error) {
      if (!this.cleaned && this.connection.provider) {
        provider.emitError(PeerErrorType.WebRTC, error);
        this.connection.close();
      }
    }
  }

  async handleCandidate(candidate) {
    const provider = this.connection.provider;
    const peerConnection = this.connection.peerConnection;
    if (!provider || this.cleaned || !peerConnection) return;
    try {
      await peerConnection.addIceCandidate(candidate);
    } catch (error) {
      if (!this.cleaned && this.connection.provider) {
        provider.emitError(PeerErrorType.WebRTC, error);
        this.connection.close();
      }
    }
  }

  cleanup() {
    if (this.cleaned) return;
    this.cleaned = true;
    const peerConnection = this.connection.peerConnection;
    this.connection.peerConnection = null;
    if (!peerConnection) return;
    peerConnection.onicecandidate = null;
    peerConnection.oniceconnectionstatechange = null;
    peerConnection.ondatachannel = null;
    try {
      if (peerConnection.signalingState !== 'closed') peerConnection.close();
    } catch {
      // Closing is best effort after ownership has been retired.
    }
  }
}

class DataConnection extends EventEmitter {
  static ID_PREFIX = 'dc_';

  constructor(peerId, provider, options = {}) {
    super();
    this.peer = peerId;
    this.provider = provider;
    this.options = options;
    this.metadata = options.metadata;
    this.connectionId = options.connectionId || `${DataConnection.ID_PREFIX}${randomToken()}`;
    this.label = options.label || this.connectionId;
    this.reliable = !!options.reliable;
    this.serialization = 'json';
    this._open = false;
    this._closed = false;
    this.peerConnection = null;
    this.dataChannel = null;
    this.negotiator = new Negotiator(this);
    this.negotiator.startConnection(options._payload || {
      originator: true,
      reliable: this.reliable,
    });
  }

  get type() {
    return ConnectionType.Data;
  }

  get open() {
    return this._open;
  }

  emitError(type, message) {
    this.emit('error', new PeerError(type, message));
  }

  initializeDataChannel(dataChannel) {
    if (this._closed) {
      try { dataChannel.close(); } catch { /* terminal */ }
      return;
    }
    if (this.dataChannel === dataChannel) return;
    const previous = this.dataChannel;
    if (previous) {
      previous.onopen = null;
      previous.onmessage = null;
      previous.onclose = null;
      previous.onerror = null;
      try { previous.close(); } catch { /* stale channel */ }
    }
    this.dataChannel = dataChannel;
    try { dataChannel.binaryType = 'arraybuffer'; } catch { /* read-only in a test double */ }
    dataChannel.onopen = () => {
      if (this._closed) return;
      this._open = true;
      this.emit('open');
    };
    dataChannel.onmessage = (event) => this.receive(event.data);
    dataChannel.onclose = () => this.close();
    dataChannel.onerror = (error) => {
      if (this._closed) return;
      this.emitError('connection-closed', error || 'Data channel error');
      this.close();
    };
  }

  receive(data) {
    if (this._closed) return;
    if (data instanceof Blob) {
      if (data.size > PEER_MESSAGE_LIMIT_BYTES) {
        this.emitError('message-too-big', 'Message exceeds the JSON channel limit');
        this.close();
        return;
      }
      void data.arrayBuffer().then((buffer) => this.receive(buffer)).catch((error) => {
        if (!this._closed) {
          this.emitError('connection-closed', error);
          this.close();
        }
      });
      return;
    }
    const bytes = messageBytes(data);
    if (!bytes || bytes.byteLength > PEER_MESSAGE_LIMIT_BYTES) {
      this.emitError('message-too-big', 'Message exceeds the JSON channel limit');
      this.close();
      return;
    }
    try {
      const decoded = JSON.parse(new TextDecoder().decode(bytes));
      if (decoded?.__peerData?.type === 'close') {
        this.close();
        return;
      }
      this.emit('data', decoded);
    } catch (error) {
      this.emitError('connection-closed', error);
      this.close();
    }
  }

  send(data) {
    if (!this.open || !this.dataChannel) {
      this.emitError('not-open-yet', 'Connection is not open. Listen for the open event before sending.');
      return false;
    }
    if (this.dataChannel.bufferedAmount > MAX_BUFFERED_AMOUNT) {
      this.emitError('connection-closed', 'Data channel buffer is full');
      this.close();
      return false;
    }
    let encoded;
    try {
      const serialized = JSON.stringify(data);
      if (typeof serialized !== 'string') throw new Error('JSON message is not serializable');
      encoded = new TextEncoder().encode(serialized);
    } catch (error) {
      this.emitError('connection-closed', error);
      return false;
    }
    if (encoded.byteLength > PEER_MESSAGE_LIMIT_BYTES) {
      this.emitError('message-too-big', 'Message exceeds the JSON channel limit');
      return false;
    }
    try {
      this.dataChannel.send(encoded);
      return true;
    } catch (error) {
      this.emitError('connection-closed', error);
      this.close();
      return false;
    }
  }

  async handleMessage(message) {
    const payload = message?.payload;
    if (!payload || !this.negotiator) return;
    if (message.type === ServerMessageType.Answer) {
      await this.negotiator.handleSDP(ServerMessageType.Answer, payload.sdp);
    } else if (message.type === ServerMessageType.Candidate) {
      await this.negotiator.handleCandidate(payload.candidate);
    }
  }

  close(options = {}) {
    if (options.flush) {
      this.send({ __peerData: { type: 'close' } });
      return;
    }
    if (this._closed) return;
    this._closed = true;
    this._open = false;
    const negotiator = this.negotiator;
    this.negotiator = null;
    negotiator?.cleanup();
    const provider = this.provider;
    this.provider = null;
    provider?._removeConnection(this);
    const dataChannel = this.dataChannel;
    this.dataChannel = null;
    if (dataChannel) {
      dataChannel.onopen = null;
      dataChannel.onmessage = null;
      dataChannel.onclose = null;
      dataChannel.onerror = null;
      try { dataChannel.close(); } catch { /* terminal */ }
    }
    this.emit('close');
  }
}

class Peer extends EventEmitter {
  static DEFAULT_KEY = 'peerjs';

  constructor(idOrOptions, maybeOptions) {
    super();
    let userId;
    let options = maybeOptions || {};
    if (isRecord(idOrOptions)) options = idOrOptions;
    else if (idOrOptions !== undefined && idOrOptions !== null) userId = String(idOrOptions);
    this.options = {
      debug: 0,
      host: CLOUD_HOST,
      port: CLOUD_PORT,
      path: '/',
      key: Peer.DEFAULT_KEY,
      token: randomToken(),
      config: DEFAULT_CONFIG,
      referrerPolicy: 'strict-origin-when-cross-origin',
      ...options,
    };
    if (this.options.host === '/') this.options.host = location.hostname;
    if (this.options.path && !this.options.path.startsWith('/')) this.options.path = `/${this.options.path}`;
    if (this.options.path && !this.options.path.endsWith('/')) this.options.path += '/';
    if (this.options.secure === undefined) this.options.secure = this.options.host === CLOUD_HOST || location.protocol === 'https:';
    logger.level = this.options.debug || 0;
    this._id = null;
    this._lastServerId = null;
    this._open = false;
    this._destroyed = false;
    this._disconnected = false;
    this._connections = new Map();
    this._lostMessages = new Map();
    this._api = new API(this.options);
    this._socket = this.createServerConnection();
    if (!util.supports.webRTC) {
      this.delayedAbort(PeerErrorType.BrowserIncompatible, 'The current browser does not support WebRTC');
      return;
    }
    if (userId && !validId(userId)) {
      this.delayedAbort(PeerErrorType.InvalidID, `ID "${userId}" is invalid`);
      return;
    }
    if (userId) this.initialize(userId);
    else void this._api.retrieveId().then((id) => {
      if (!this.destroyed && !this.disconnected) this.initialize(id);
    }).catch((error) => this.abort(PeerErrorType.ServerError, error));
  }

  get id() {
    return this._id;
  }

  get open() {
    return this._open;
  }

  get destroyed() {
    return this._destroyed;
  }

  get disconnected() {
    return this._disconnected;
  }

  get socket() {
    return this._socket;
  }

  get connections() {
    const result = Object.create(null);
    for (const [peerId, connections] of this._connections) result[peerId] = connections;
    return result;
  }

  emitError(type, message) {
    this.emit('error', new PeerError(type, message));
  }

  createServerConnection() {
    const socket = new Socket(
      this.options.secure,
      this.options.host,
      this.options.port,
      this.options.path,
      this.options.key,
      this.options.pingInterval,
    );
    socket.on(SocketEventType.Message, (message) => this.handleMessage(message));
    socket.on(SocketEventType.Error, (error) => this.abort(PeerErrorType.SocketError, error));
    socket.on(SocketEventType.Disconnected, () => {
      if (this.disconnected) return;
      this.emitError(PeerErrorType.Network, 'Lost connection to server.');
      this.disconnect();
    });
    socket.on(SocketEventType.Close, () => {
      if (!this.disconnected) this.abort(PeerErrorType.SocketClosed, 'Underlying socket is already closed.');
    });
    return socket;
  }

  initialize(id) {
    if (this.destroyed || this.disconnected) return;
    this._id = id;
    this.socket.start(id, this.options.token);
  }

  handleMessage(message) {
    if (!isRecord(message)) return;
    const { type, payload, src: peerId } = message;
    switch (type) {
      case ServerMessageType.Open:
        this._lastServerId = this.id;
        this._open = true;
        this.emit('open', this.id);
        break;
      case ServerMessageType.Error:
        this.abort(PeerErrorType.ServerError, payload?.msg || 'PeerServer error');
        break;
      case ServerMessageType.IdTaken:
        this.abort(PeerErrorType.UnavailableID, `ID "${this.id}" is taken`);
        break;
      case ServerMessageType.InvalidKey:
        this.abort(PeerErrorType.InvalidKey, `API KEY "${this.options.key}" is invalid`);
        break;
      case ServerMessageType.Leave:
        this.cleanupPeer(peerId);
        this._connections.delete(peerId);
        break;
      case ServerMessageType.Expire:
        this.emitError(PeerErrorType.PeerUnavailable, `Could not connect to peer ${peerId}`);
        break;
      case ServerMessageType.Offer: {
        if (!isRecord(payload) || payload.type !== ConnectionType.Data || payload.serialization !== 'json') {
          this.emitError(PeerErrorType.ServerError, 'Only JSON data connections are supported');
          return;
        }
        const connectionId = payload.connectionId;
        const existing = this.getConnection(peerId, connectionId);
        existing?.close();
        let connection;
        try {
          connection = new DataConnection(peerId, this, {
            connectionId,
            payload,
            _payload: payload,
            metadata: payload.metadata,
            label: payload.label,
            reliable: payload.reliable,
          });
        } catch (error) {
          this.emitError(PeerErrorType.WebRTC, error);
          return;
        }
        this.addConnection(peerId, connection);
        this.emit('connection', connection);
        for (const lost of this.getMessages(connectionId)) void connection.handleMessage(lost);
        break;
      }
      default: {
        if (!isRecord(payload) || typeof payload.connectionId !== 'string') return;
        const connection = this.getConnection(peerId, payload.connectionId);
        if (connection?.peerConnection) void connection.handleMessage(message);
        else this.storeMessage(payload.connectionId, message);
      }
    }
  }

  storeMessage(connectionId, message) {
    let messages = this._lostMessages.get(connectionId);
    if (!messages) {
      if (this._lostMessages.size >= MAX_LOST_MESSAGE_CONNECTIONS) {
        const oldest = this._lostMessages.keys().next().value;
        if (oldest !== undefined) this._lostMessages.delete(oldest);
      }
      messages = [];
      this._lostMessages.set(connectionId, messages);
    }
    if (messages.length >= MAX_LOST_MESSAGES) messages.shift();
    messages.push(message);
  }

  getMessages(connectionId) {
    const messages = this._lostMessages.get(connectionId) || [];
    this._lostMessages.delete(connectionId);
    return messages;
  }

  connect(peerId, options = {}) {
    if (this.disconnected) {
      this.emitError(PeerErrorType.Disconnected, 'Cannot connect after disconnecting from server.');
      return null;
    }
    if (options.serialization !== undefined && options.serialization !== 'json') {
      this.emitError(PeerErrorType.ServerError, 'Only JSON data connections are supported');
      return null;
    }
    const connection = new DataConnection(peerId, this, { ...options, serialization: 'json' });
    this.addConnection(peerId, connection);
    return connection;
  }

  addConnection(peerId, connection) {
    const connections = this._connections.get(peerId) || [];
    connections.push(connection);
    this._connections.set(peerId, connections);
  }

  _removeConnection(connection) {
    const connections = this._connections.get(connection.peer);
    if (connections) {
      const index = connections.indexOf(connection);
      if (index >= 0) connections.splice(index, 1);
      if (connections.length === 0) this._connections.delete(connection.peer);
    }
    this._lostMessages.delete(connection.connectionId);
  }

  getConnection(peerId, connectionId) {
    return this._connections.get(peerId)?.find((connection) => connection.connectionId === connectionId) || null;
  }

  delayedAbort(type, message) {
    setTimeout(() => this.abort(type, message), 0);
  }

  abort(type, message) {
    this.emitError(type, message);
    if (this._lastServerId) this.disconnect();
    else this.destroy();
  }

  cleanupPeer(peerId) {
    for (const connection of this._connections.get(peerId) || []) connection.close();
  }

  cleanup() {
    for (const peerId of this._connections.keys()) {
      this.cleanupPeer(peerId);
      this._connections.delete(peerId);
    }
    this.socket.removeAllListeners();
  }

  destroy() {
    if (this.destroyed) return;
    this.disconnect();
    this.cleanup();
    this._destroyed = true;
    this.emit('close');
  }

  disconnect() {
    if (this.disconnected) return;
    const currentId = this.id;
    this._disconnected = true;
    this._open = false;
    this.socket.close();
    this._lastServerId = currentId;
    this._id = null;
    this.emit('disconnected', currentId);
  }

  reconnect() {
    if (this.disconnected && !this.destroyed) {
      this._disconnected = false;
      this.initialize(this._lastServerId);
      return;
    }
    if (this.destroyed) throw new Error('This peer cannot reconnect after destroy.');
    if (!this.disconnected && !this.open) return;
    throw new Error(`Peer ${this.id} cannot reconnect because it is not disconnected.`);
  }

  listAllPeers(callback = () => {}) {
    void this._api.listAllPeers().then(callback).catch((error) => this.abort(PeerErrorType.ServerError, error));
  }
}

export { DataConnection, PEER_MESSAGE_LIMIT_BYTES, Peer };
export default Peer;
